# Querying Custom Tile Data under the Player in Godot 4.3 TileMapLayer:
extends Node2D

@onready var ground_layer: TileMapLayer = $GroundLayer

func get_tile_surface_at(world_pos: Vector2) -> String:
    var local_pos: Vector2 = ground_layer.to_local(world_pos)
    var cell: Vector2i = ground_layer.local_to_map(local_pos)
    var data: TileData = ground_layer.get_cell_tile_data(cell)
    if data == null:
        return "void"
    return str(data.get_custom_data("surface"))

# Same-Frame Line-of-Sight Check with RayCast2D:
extends CharacterBody2D

@onready var sight_ray: RayCast2D = $SightRay

func can_see_target(target: Node2D, max_distance: float = 320.0) -> bool:
    if global_position.distance_to(target.global_position) > max_distance:
        return false
    sight_ray.target_position = to_local(target.global_position)
    sight_ray.force_raycast_update()
    return sight_ray.is_colliding() and sight_ray.get_collider() == target

