# Obstacle-Avoiding AI Movement with NavigationAgent2D:
extends CharacterBody2D

@export var move_speed: float = 140.0
@onready var nav_agent: NavigationAgent2D = $NavigationAgent2D

func update_target(world_target: Vector2) -> void:
    nav_agent.target_position = world_target

func _physics_process(_delta: float) -> void:
    if nav_agent.is_navigation_finished():
        velocity = Vector2.ZERO
        return
    var next_wp: Vector2 = nav_agent.get_next_path_position()
    velocity = global_position.direction_to(next_wp) * move_speed
    move_and_slide()

# Controlling an AnimationTree StateMachine + BlendSpace2D:
extends CharacterBody2D

@onready var anim_tree: AnimationTree = $AnimationTree
@onready var state_machine: AnimationNodeStateMachinePlayback = anim_tree.get("parameters/playback")

func update_character_animation(move_dir: Vector2) -> void:
    if move_dir != Vector2.ZERO:
        # Update facing direction on both Idle and Walk BlendSpace2D nodes:
        anim_tree.set("parameters/Idle/blend_position", move_dir)
        anim_tree.set("parameters/Walk/blend_position", move_dir)
        state_machine.travel("Walk")
    else:
        state_machine.travel("Idle")

# Pulsing 2D Torch / Tabletop Spotlight with PointLight2D:
extends PointLight2D

@export var base_energy: float = 1.15
@export var flicker_amount: float = 0.12
var _time: float = 0.0

func _process(delta: float) -> void:
    _time += delta * 7.5
    energy = base_energy + sin(_time) * flicker_amount
